def count_equivalence_classes(S):
    n = len(S)
    classes = {}

    for i in range(n):
        for j in range(i, n):
            substring = S[i:j+1]
            even_ones_count = substring.count('1') % 2 == 0
            if even_ones_count:
                reversed_substring = substring[::-1]
                classes[reversed_substring] = None

    return len(set(classes.keys()))

